create table public.nk_accounts(id uuid primary key default gen_random_uuid(), token_hash text unique not null, created_at timestamptz not null default now());
create table public.nk_profiles(id uuid primary key references public.nk_accounts(id) on delete cascade, username text unique not null check(username ~ '^[A-Za-z0-9_]{3,20}$'), avatar text not null default 'knight' check(avatar in ('knight','rook','queen','king','bishop','pawn')), bio text not null default '' check(length(bio)<=160), created_at timestamptz not null default now());
create unique index nk_profiles_username_lower on public.nk_profiles(lower(username));
create table public.nk_games(id uuid primary key default gen_random_uuid(), white_id uuid not null references public.nk_profiles(id), black_id uuid references public.nk_profiles(id), status text not null default 'waiting' check(status in ('waiting','active','finished','cancelled')), fen text not null default 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1', moves jsonb not null default '[]', version integer not null default 0, result text, finish_reason text, draw_offer uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(black_id is null or black_id<>white_id));
create index nk_games_status_updated on public.nk_games(status,updated_at desc);
create index nk_games_white on public.nk_games(white_id);
create index nk_games_black on public.nk_games(black_id);
create table public.nk_messages(id uuid primary key default gen_random_uuid(), author_id uuid not null references public.nk_profiles(id), body text not null check(length(body) between 1 and 300), created_at timestamptz not null default now());
create index nk_messages_created on public.nk_messages(created_at desc);
create table public.nk_posts(id uuid primary key default gen_random_uuid(), author_id uuid not null references public.nk_profiles(id), title text not null check(length(title) between 3 and 100), body text not null check(length(body) between 1 and 1500), created_at timestamptz not null default now());
create index nk_posts_created on public.nk_posts(created_at desc);
create table public.nk_replies(id uuid primary key default gen_random_uuid(), post_id uuid not null references public.nk_posts(id) on delete cascade, author_id uuid not null references public.nk_profiles(id), body text not null check(length(body) between 1 and 600), created_at timestamptz not null default now());
create index nk_replies_post on public.nk_replies(post_id,created_at);
create table public.nk_reports(id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.nk_profiles(id), target_type text not null check(target_type in ('message','post','reply')), target_id uuid not null, created_at timestamptz not null default now(), unique(reporter_id,target_type,target_id));
create table public.nk_limits(key text primary key, window_start timestamptz not null, hits integer not null);
alter table public.nk_accounts enable row level security;
alter table public.nk_profiles enable row level security;
alter table public.nk_games enable row level security;
alter table public.nk_messages enable row level security;
alter table public.nk_posts enable row level security;
alter table public.nk_replies enable row level security;
alter table public.nk_reports enable row level security;
alter table public.nk_limits enable row level security;
revoke all on public.nk_accounts,public.nk_profiles,public.nk_games,public.nk_messages,public.nk_posts,public.nk_replies,public.nk_reports,public.nk_limits from anon,authenticated;
grant all on public.nk_accounts,public.nk_profiles,public.nk_games,public.nk_messages,public.nk_posts,public.nk_replies,public.nk_reports,public.nk_limits to service_role;
create function public.nk_rate_limit(bucket text, seconds integer, max_hits integer) returns boolean language sql security invoker set search_path='' as $$
 with changed as (insert into public.nk_limits as l(key,window_start,hits) values(bucket,now(),1) on conflict(key) do update set hits=case when l.window_start < now()-make_interval(secs=>seconds) then 1 else l.hits+1 end,window_start=case when l.window_start < now()-make_interval(secs=>seconds) then now() else l.window_start end returning hits) select hits<=max_hits from changed;
$$;
revoke all on function public.nk_rate_limit(text,integer,integer) from public,anon,authenticated;
grant execute on function public.nk_rate_limit(text,integer,integer) to service_role;
